<?php $absoluteImage=static fn(?string $path):string=>preg_match('#^https?://#i',$url=upload_url($path))?$url:rtrim((string)config('app.url'),'/').'/'.ltrim($url,'/'); ?>
<!doctype html><html lang="ro"><body style="margin:0;background:#ede7e1;font-family:Arial,sans-serif;color:#302923"><table role="presentation" width="100%"><tr><td align="center" style="padding:28px 12px"><table role="presentation" width="680" style="width:100%;max-width:680px;background:white;border-radius:20px;overflow:hidden"><tr><td style="padding:26px 32px;background:#3e3029;color:white"><p style="margin:0 0 7px;color:#d7bba8;font-size:11px;font-weight:bold;letter-spacing:2px">COMANDĂ NOUĂ ÎN CRM</p><h1 style="margin:0;font-family:Georgia,serif;font-weight:normal"><?=e($order['order_number'])?> · <?=money($order['total'])?></h1></td></tr><tr><td style="padding:26px 32px"><div style="padding:16px 18px;background:#f8eee6;border-radius:14px;line-height:1.65"><strong><?=e($order['first_name'].' '.$order['last_name'])?></strong><br><?=e($order['email'])?> · <?=e($order['phone'])?><br><?=e($order['shipping_address'])?>, <?=e($order['shipping_city'])?>, <?=e($order['shipping_county'])?></div><table role="presentation" width="100%" style="margin-top:18px;border-collapse:collapse"><?php foreach($items as $item):$addons=(array)json_decode((string)($item['addons_json']??''),true);$personalization=(array)json_decode((string)($item['customization_json']??''),true);?><tr><td style="padding:14px 0;border-bottom:1px solid #eadbd0" width="60"><img src="<?=e($absoluteImage($item['image_path']??null))?>" width="48" height="48" style="object-fit:cover;border-radius:10px" alt=""></td><td style="padding:14px 10px;border-bottom:1px solid #eadbd0"><strong><?=e($item['product_name'])?></strong><?php if(!empty($item['variant_name'])):?><br><small><?=e($item['variant_name'])?></small><?php endif?><br><small><?= (int)$item['quantity']?> × <?=money($item['price'])?></small><?php if($personalization):?><br><small style="color:#925f40">✦ <?php foreach($personalization as $i=>$detail):?><?=$i?' · ':''?><?=e($detail['label']??'')?>: <?=e($detail['value']??'')?><?php endforeach?></small><?php endif?><?php foreach($addons as $addon):?><br><small>＋ <?=e($addon['name']??'Produs')?> · <?= (int)($addon['quantity']??1)?> × <?=money($addon['price']??0)?></small><?php endforeach?></td><td align="right" style="padding:14px 0;border-bottom:1px solid #eadbd0;font-weight:bold"><?=money($item['total'])?></td></tr><?php endforeach?></table><table role="presentation" width="100%"><tr><td style="padding-top:16px">Subtotal<br>Livrare<?php if((float)$order['payment_fee']>0):?><br>Taxă plată<?php endif?></td><td align="right" style="padding-top:16px"><?=money($order['subtotal'])?><br><?= (float)$order['shipping_total']>0?money($order['shipping_total']):'Gratuită' ?><?php if((float)$order['payment_fee']>0):?><br><?=money($order['payment_fee'])?><?php endif?></td></tr><tr><td style="padding-top:12px;font:22px Georgia,serif">Total</td><td align="right" style="padding-top:12px;font:bold 23px Georgia,serif"><?=money($order['total'])?></td></tr></table><p style="margin:26px 0 0;text-align:center"><a href="<?=e(rtrim((string)config('app.url'),'/').'/admin/comenzi/'.(int)$order['id'])?>" style="display:inline-block;padding:14px 24px;background:#9b6d50;color:white;border-radius:999px;text-decoration:none;font-weight:bold;font-size:12px">DESCHIDE COMANDA ÎN CRM</a></p></td></tr></table></td></tr></table></body></html>
